for root in [Path('experiments/e1'),Path('experiments/e2'),Path('experiments/e3'),Path('experiments/e4')]:
    if not root.exists(): continue
    for p in root.glob('*.md'):
        txt=p.read_text()
        if 'normal' in txt.lower() and ('quasitrace' in txt.lower() or 'quasi-trace' in txt.lower()):
            print('\n###',p)
            for line in txt.splitlines():
                if 'normal' in line.lower() or 'continu' in line.lower(): print(line[:500])

